//! 🔎️ A real original instance executes and closes a phased guest call without rebuilding its Core or borrowing invented currency.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::RetainedCloneGrant;
fn clock()->Option<u64>{Some(1000)}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:2_000_000,maximum_capacity_bytes:2_000_000,maximum_release_bytes:2_000_000,maximum_depth:64}}
fn observed<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn core_bytes(component:&[u8])->&[u8]{let mut pc=9;let mut length=0;let mut shift=0;loop{let byte=component[pc];pc+=1;length|=usize::from(byte&127)<<shift;shift+=7;if byte&128==0{break}}&component[pc..pc+length]}
/// 🧮️ Actual Wasmtime scalar output agrees while original Core ownership, measured instructions and every physical receipt stay intact.
#[test]
fn original_owned_guest_call_preserves_source_core_machine_and_independent_execution(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let bytes=super::super::owned_runtime_tests::owned_channel_guest(semio_framework_os_kernel::CHANNEL_VERSION);let engine=wasmtime::Engine::default();let module=wasmtime::Module::new(&engine,core_bytes(&bytes)).unwrap();let mut store=wasmtime::Store::new(&engine,());let oracle=wasmtime::Instance::new(&mut store,&module,&[]).unwrap();let expected=oracle.get_typed_func::<(),i64>(&mut store,OwnedSemioExport::ChannelVersion.core_name()).unwrap().call(&mut store,()).unwrap();let runtime=OwnedRuntime::new(clock);let compiled=runtime.compile_component(&bytes).unwrap();let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut startup=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_actor_startup(&compiled,cx)}).unwrap();let mut born=0;let mut released=0;
 for _ in 0..150{if startup.as_ref().unwrap().ready(){break}epoch+=1;let(_,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:1024,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;let owner=startup.as_mut().unwrap();let execution=owner.requires_execution().then(||OriginalGuestExecutionBudget{input:RetainedTurnInput{operation:71,generation:3,epoch,grant:cx.retained_grant()},fuel:1,deadline_us:cx.deadline_us()});owner.advance_step(&compiled,cx,execution)?.result?;Ok(())}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;}
 let mut state=None;for _ in 0..3{epoch+=1;state=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.take_actor_startup_step(&mut startup,&compiled,RetainedTurnInput{operation:71,generation:3,epoch,grant:cx.retained_grant()},cx)}).unwrap();if state.is_some(){break}}let mut state=state.unwrap();let pointer=state.original_memory(0).unwrap().as_ptr();epoch+=1;let(ready,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:0,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_original_call_step(&mut state,OwnedSemioExport::ChannelVersion,&[],cx)}).unwrap());assert!(!ready);assert!(!state.original_call_is_pending());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());epoch+=1;assert!(caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_original_call_step(&mut state,OwnedSemioExport::ChannelVersion,&[],cx)}).unwrap());let mut vm=0;for _ in 0..40{epoch+=1;let(call,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;let execution=state.original_call_requires_execution().then(||OriginalGuestExecutionBudget{input:RetainedTurnInput{operation:71,generation:3,epoch,grant:cx.retained_grant()},fuel:1,deadline_us:cx.deadline_us()});runtime.advance_original_call_step(&mut state,execution,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;if let Some(execution)=call.execution{vm+=execution.spent_fuel.unwrap()}if call.result.unwrap()==OwnedOriginalCallStatus::Ready{break}}assert_eq!(vm,fixture["expectedVm"].as_u64().unwrap());assert_eq!(state.original_memory(0).unwrap().as_ptr(),pointer);epoch+=1;let(result,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:0,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;runtime.take_original_call_result_step(&mut state,cx)}).unwrap());assert!(result.is_none());assert!(state.original_call_is_pending());assert_eq!(heap,(0,0));let mut foreign=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let(result,heap)=observed(||foreign.turn(stock,|cx|{cx.bind_original_source_epoch(epoch+1)?;runtime.take_original_call_result_step(&mut state,cx)}));assert!(result.is_err());assert_eq!(heap,(0,0));foreign.retire(stock);epoch+=1;let result=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.take_original_call_result_step(&mut state,cx)}).unwrap().unwrap();assert_eq!(result.value,Some(Value::I64(expected)));assert_eq!((result.input.operation,result.input.generation),(71,3));assert!(!state.original_call_is_pending());epoch+=1;assert!(caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_original_call_step(&mut state,OwnedSemioExport::ChannelVersion,&[],cx)}).unwrap());caller.cancel().cancel_now();for _ in 0..40{epoch+=1;let(done,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.close_original_call_step(&mut state,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;if done{break}}assert!(!state.original_call_is_pending());let mut state=Some(state);for _ in 0..100{if state.is_none(){break}epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.close_original_actor_step(&mut state,&compiled,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(state.is_none());assert_eq!(born,released);caller.retire(stock);eprintln!("[DEBUG] actual original guest call WasmtimeScalar={expected} measuredVM={vm} samePaidCore=true deniedHeaderAndResultCopy=true foreignSameBusinessSourceRefused=true cancelledMachineClose=true physicalBirth={born} paidRelease={released}");
}
